// Strategy: Build a controlled ByteArraySource from random data and provide
// an UncheckedByteArraySink backed by a sufficiently large buffer sized via
// MaxCompressedLength. This guarantees no overflow on the sink.
{
  // Generate input up to 1500 bytes (keep under 2KB for performance)
  std::string in = FUZZ_PARAM_STR();
  if (in.size() > 1500) in.resize(1500);

  // Construct Source on the fuzzed input
  snappy::ByteArraySource src(in.data(), in.size());

  // Allocate destination buffer with worst-case size
  size_t max_out = snappy::MaxCompressedLength(in.size());
  if (max_out > 2048) max_out = 2048; // cap for fuzzer perf; still >= in.size() for small in
  // Ensure at least 1 byte of capacity
  if (max_out == 0) max_out = 1;
  char* out_buf = new char[max_out];
  snappy::UncheckedByteArraySink sink(out_buf);

  // Invoke target
  size_t written = snappy::Compress(&src, &sink);

  // Validate that written never exceeds our buffer (API guarantee when sized via MaxCompressedLength)
  FUZZ_ASSERT(written <= max_out, "snappy::Compress wrote past provided sink capacity");

  // Cleanup of local buffer
  delete[] out_buf;
}

