import os
import random
import struct
from typing import List

# This generator produces arbitrary binary data that is particularly
# useful for exercising Snappy Source/Sink and (de)compression paths.
# It biases towards realistic text/binary segments, repeated patterns,
# varying lengths, and includes some edge-case constructs like runs of
# zeros, small alphabets (to compress well), and high-entropy blocks.

_MAX_OUTPUT = 4096

def _rand_bytes(rng: random.Random, n: int) -> bytes:
    return bytes(rng.getrandbits(8) for _ in range(n))

def _repeated_block(rng: random.Random, alphabet: bytes, min_len: int, max_len: int) -> bytes:
    # Build a block from a small alphabet to encourage high compressibility.
    size = rng.randint(min_len, max_len)
    if not alphabet:
        alphabet = b"\x00"
    return bytes(alphabet[rng.randrange(len(alphabet))] for _ in range(size))

def _pattern_block(rng: random.Random, min_len: int, max_len: int) -> bytes:
    size = rng.randint(min_len, max_len)
    # Choose a short pattern and repeat with some noise
    pat_len = rng.randint(1, min(64, max(1, size // 8 or 1)))
    pat = _rand_bytes(rng, pat_len)
    out = bytearray()
    while len(out) < size:
        # Mostly repeat the pattern, sometimes mutate a byte
        chunk = bytearray(pat)
        if rng.random() < 0.2 and len(chunk) > 0:
            idx = rng.randrange(len(chunk))
            chunk[idx] = rng.randrange(256)
        take = min(len(chunk), size - len(out))
        out.extend(chunk[:take])
    return bytes(out)

def _text_block(rng: random.Random, min_len: int, max_len: int) -> bytes:
    size = rng.randint(min_len, max_len)
    # Mix ASCII text with whitespace and newlines
    letters = b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789" \
              b" .,_-:/\\n\r\t()[]{}<>!@#$%^&*?=+";
    # Create sentences with some repetition
    words = [b"lorem", b"ipsum", b"dolor", b"sit", b"amet", b"snappy", b"compress", b"decompress"]
    out = bytearray()
    while len(out) < size:
        if rng.random() < 0.6:
            w = rng.choice(words)
            out.extend(w)
        else:
            out.append(letters[rng.randrange(len(letters))])
        if rng.random() < 0.15:
            out.append(ord('\n'))
        if rng.random() < 0.1:
            out.extend(b" ")
        if rng.random() < 0.05:
            # add a short repeated sequence
            rep = rng.choice(words)
            out.extend(rep * rng.randint(1, 3))
    return bytes(out[:size])

def _numeric_block(rng: random.Random, min_len: int, max_len: int) -> bytes:
    # Mixture of little/big-endian integers to simulate binary structs.
    target = rng.randint(min_len, max_len)
    out = bytearray()
    while len(out) + 8 <= target:
        if rng.random() < 0.5:
            out.extend(struct.pack('<I', rng.getrandbits(32)))
        else:
            out.extend(struct.pack('>I', rng.getrandbits(32)))
        if rng.random() < 0.3:
            out.extend(struct.pack('<H', rng.getrandbits(16)))
        if rng.random() < 0.2:
            out.extend(struct.pack('>Q', rng.getrandbits(64)))
        if len(out) > target:
            break
    # Fill remainder with random bytes
    rem = target - len(out)
    if rem > 0:
        out.extend(_rand_bytes(rng, rem))
    return bytes(out[:target])

def _high_entropy_block(rng: random.Random, min_len: int, max_len: int) -> bytes:
    return _rand_bytes(rng, rng.randint(min_len, max_len))

def _zero_block(rng: random.Random, min_len: int, max_len: int) -> bytes:
    return bytes(rng.randint(min_len, max_len))

def _small_alphabet(rng: random.Random) -> bytes:
    # Create a tiny alphabet (1..6 unique bytes), often very compressible when repeated.
    k = rng.randint(1, 6)
    # Bias to ascii letters and some control bytes
    pool = list(b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789\x00\x01\x02\xff")
    rng.shuffle(pool)
    return bytes(pool[:k])

def _assemble(rng: random.Random, target_len: int) -> bytes:
    # Build a sequence of varied blocks until reaching target length.
    blocks: List[bytes] = []
    remain = target_len
    # Start with a header-like prelude of varied bytes to exercise Peek/Skip regions
    if remain > 0:
        pre = _numeric_block(rng, 0, min(32, remain))
        blocks.append(pre)
        remain -= len(pre)

    while remain > 0:
        kind = rng.random()
        max_chunk = max(1, min(remain, 512))
        min_chunk = 1
        if kind < 0.18:
            blocks.append(_zero_block(rng, min_chunk, max_chunk))
        elif kind < 0.36:
            blocks.append(_high_entropy_block(rng, min_chunk, max_chunk))
        elif kind < 0.54:
            blocks.append(_pattern_block(rng, min_chunk, max_chunk))
        elif kind < 0.72:
            blocks.append(_text_block(rng, min_chunk, max_chunk))
        elif kind < 0.90:
            alpha = _small_alphabet(rng)
            blocks.append(_repeated_block(rng, alpha, min_chunk, max_chunk))
        else:
            blocks.append(_numeric_block(rng, min_chunk, max_chunk))
        remain = target_len - sum(len(b) for b in blocks)

    data = b"".join(blocks)
    # Trim to exactly target_len
    if len(data) > target_len:
        data = data[:target_len]
    return data

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Choose a total length with a distribution covering small and larger buffers
    roll = rng.random()
    if roll < 0.15:
        total = rng.randint(0, 32)   # tiny, including empty
    elif roll < 0.60:
        total = rng.randint(33, 512) # small/medium
    elif roll < 0.90:
        total = rng.randint(513, 2048)
    else:
        total = rng.randint(2049, _MAX_OUTPUT)

    # Assemble diversified content of the chosen size
    data = _assemble(rng, total)

    # Occasionally prepend or append small segments to vary boundaries
    if len(data) < _MAX_OUTPUT and rng.random() < 0.3:
        pad = _rand_bytes(rng, rng.randint(1, min(32, _MAX_OUTPUT - len(data))))
        if rng.random() < 0.5:
            data = pad + data
        else:
            data = data + pad
        if len(data) > _MAX_OUTPUT:
            data = data[:_MAX_OUTPUT]

    return data
